contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount, uint minSumValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(collectAmount > 0);
        require(collectAmount <= depositAmount);
        require(minSumValue <= depositAmount);
        require(address(this).balance >= depositAmount);

        c.SetMinSum(minSumValue); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint beforeUser = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterUser = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted || afterUser == beforeUser - collectAmount);
    }

    receive() external payable {}
}

